from typing import List, Tuple

def top_words(text: str, k: int) -> List[Tuple[str, int]]:
    if k <= 0:
        return []

    # Dictionary to store word counts
    word_counts: dict[str, int] = {}

    # Process text to extract words
    # A word is a maximal run of ASCII letters a-z after lower-casing
    current_word = ""

    for char in text.lower():
        if 'a' <= char <= 'z':
            current_word += char
        else:
            if current_word:
                word_counts[current_word] = word_counts.get(current_word, 0) + 1
                current_word = ""

    # Don't forget the last word if text ends with a letter
    if current_word:
        word_counts[current_word] = word_counts.get(current_word, 0) + 1

    # Convert to list and sort by count descending, then word ascending
    sorted_words = sorted(word_counts.items(), key=lambda x: (-x[1], x[0]))

    # Return top k words
    return sorted_words[:k]
