import csv
from typing import Dict, List, Any

def column_means(csv_text: str) -> Dict[str, float]:
    """
    Calculate the mean of numeric values for each column in a CSV text.

    Args:
        csv_text: A string containing CSV data with a header row.

    Returns:
        A dictionary mapping column names to their mean values (float).
        Only includes columns where all non-empty cells are valid floats.
    """
    reader = csv.reader(csv_text.splitlines())

    try:
        header = next(reader)
    except StopIteration:
        return {}

    # Dictionary to store sums and counts for each column
    column_data: Dict[str, List[float]] = {col: [] for col in header}

    for row in reader:
        # Ensure the row has enough columns (pad with empty strings if needed)
        while len(row) < len(header):
            row.append("")

        for idx, col_name in enumerate(header):
            cell_value = row[idx]

            # Skip empty cells
            if not cell_value or cell_value.strip() == "":
                continue

            # Try to parse as float
            try:
                value = float(cell_value)
                column_data[col_name].append(value)
            except ValueError:
                # If parsing fails, this column is invalid and should be skipped entirely
                return {}

    # Calculate means for columns that have data
    result: Dict[str, float] = {}
    for col_name, values in column_data.items():
        if values:
            result[col_name] = sum(values) / len(values)

    return result
