import heapq
from typing import Dict, List, Tuple, Union

def shortest_path(graph: Dict[str, Dict[str, float]], start: str, goal: str) -> Tuple[float, List[str]]:
    """
    Finds the shortest path from start to goal in a directed graph with non-negative weights.

    Args:
        graph: Dictionary representing the graph where graph[u][v] is the weight of edge u->v.
               Nodes may only appear as targets (outgoing edges).
        start: The starting node.
        goal: The target node.

    Returns:
        A tuple (total_cost, path) where total_cost is the sum of edge weights and 
        path is a list of nodes from start to goal inclusive.
        Returns (float("inf"), []) if no path exists or nodes are unknown.
    """
    # Handle trivial case where start equals goal
    if start == goal:
        return (0, [start])

    # Validate start node exists in graph as a source (or at least is known)
    if start not in graph and start not in graph.values():
        return (float("inf"), [])

    # Dijkstra's algorithm implementation
    # Priority queue stores tuples: (cost, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Dictionary to keep track of minimum cost to reach each node
    min_cost: Dict[str, float] = {start: 0}

    while pq:
        current_cost, current_node, current_path = heapq.heappop(pq)

        # If we've reached the goal, return the result
        if current_node == goal:
            return (current_cost, current_path)

        # Skip if we've found a shorter path to this node already
        if current_cost > min_cost.get(current_node, float("inf")):
            continue

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node].items():
                new_cost = current_cost + weight

                # If this path to neighbor is better than any previously found
                if neighbor not in min_cost or new_cost < min_cost[neighbor]:
                    min_cost[neighbor] = new_cost
                    heapq.heappush(pq, (new_cost, neighbor, current_path + [neighbor]))

    # Goal unreachable
    return (float("inf"), [])
