from typing import Optional

class EchoServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0):
        self.host = host
        self.port = port if port != 0 else None
        self.server_socket: Optional[socket.socket] = None
        self.running = False
        self.lock = threading.Lock()

    def _handle_client(self, client_socket: socket.socket) -> None:
        """Handle a single client connection."""
        try:
            while True:
                data = client_socket.recv(1024)
                if not data:
                    break

                # Decode, uppercase, and encode back
                response_data = data.decode('utf-8').upper() + '\n'
                client_socket.sendall(response_data.encode('utf-8'))
        except Exception:
            pass
        finally:
            client_socket.close()

    def start(self) -> int:
        """Start the server in the background and return the actual port."""
        if self.server_socket is not None:
            return self.server_socket.getsockname()[1]

        # Create a socket
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

        # Bind and listen
        if self.port is None:
            self.server_socket.bind((self.host, 0))
            actual_port = self.server_socket.getsockname()[1]
            self.port = actual_port
        else:
            self.server_socket.bind((self.host, self.port))

        self.server_socket.listen(5)
        self.running = True

        # Start the server thread
        server_thread = threading.Thread(target=self._accept_loop, daemon=True)
        server_thread.start()

        return self.port

    def _accept_loop(self) -> None:
        """Accept incoming connections and handle them."""
        while self.running:
            try:
                client_socket, addr = self.server_socket.accept()
                # Handle client in a new thread to avoid blocking
                t = threading.Thread(target=self._handle_client, args=(client_socket,), daemon=True)
                t.start()
            except Exception:
                if not self.running:
                    break

    def stop(self) -> None:
        """Stop the server and release the port."""
        self.running = False
        if self.server_socket is not None:
            try:
                self.server_socket.close()
            except Exception:
                pass
            self.server_socket = None
