import socket
import threading
from typing import Dict, Optional, Set

class ChatServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0):
        self.host = host
        self.port = port
        self.server_socket: Optional[socket.socket] = None
        self.clients: Dict[str, socket.socket] = {}
        self.lock = threading.Lock()
        self.running = False

    def start(self) -> int:
        if self.server_socket is not None:
            return self.port

        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

        # If port is 0, let the OS assign it
        if self.port == 0:
            self.port = self.server_socket.getsockname()[1]

        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)
        self.running = True

        # Start a thread to handle incoming connections
        connection_thread = threading.Thread(target=self._accept_loop, daemon=True)
        connection_thread.start()

        return self.port

    def stop(self):
        if not self.running:
            return
        self.running = False
        if self.server_socket:
            self.server_socket.close()
            self.server_socket = None
        # Close all client connections
        with self.lock:
            for client in self.clients.values():
                try:
                    client.close()
                except Exception:
                    pass
            self.clients.clear()

    def _accept_loop(self):
        while self.running:
            try:
                client_socket, addr = self.server_socket.accept()
                with self.lock:
                    if len(self.clients) > 0:
                        # Notify existing clients of new join
                        for existing_client in list(self.clients.values()):
                            self._broadcast(existing_client, f"* {addr[1]} joined\n")

                    self.clients[addr[1]] = client_socket
            except Exception:
                break

    def _handle_client(self, client_socket: socket.socket):
        try:
            while True:
                data = client_socket.recv(4096)
                if not data:
                    break

                lines = data.decode('utf-8').split('\n')

                for line in lines:
                    if not line.strip():
                        continue

                    # First message is registration
                    if self.clients.get(client_socket):
                        # Already registered, send error and close
                        with self.lock:
                            existing_client = list(self.clients.values())[0]
                            self._broadcast(existing_client, f"ERROR name taken\n")
                            existing_client.close()
                            del self.clients[addr[1]]
                        client_socket.close()
                        return

                    # Parse registration line: NAME <username>
                    parts = line.split(' ', 1)
                    if len(parts) != 2 or not parts[0].upper() == 'NAME':
                        continue

                    username = parts[1]

                    with self.lock:
                        if username in self.clients:
                            # Name taken, close connection
                            existing_client = self.clients[username]
                            existing_client.close()
                            del self.clients[username]
                            client_socket.close()
                            return

                        self.clients[username] = client_socket

                    # Notify others of join
                    with self.lock:
                        for other_client in list(self.clients.values()):
                            if other_client != client_socket:
                                self._broadcast(other_client, f"* {username} joined\n")

                    # Handle subsequent messages
                    while True:
                        try:
                            msg_data = client_socket.recv(4096)
                            if not msg_data:
                                break

                            msg_text = msg_data.decode('utf-8').strip()
                            if not msg_text:
                                continue

                            # Broadcast to others
                            with self.lock:
                                for other_client in list(self.clients.values()):
                                    if other_client != client_socket:
                                        self._broadcast(other_client, f"{username}: {msg_text}\n")
                        except Exception:
                            break

        except Exception:
            pass
        finally:
            # Clean up client socket
            with self.lock:
                if client_socket in self.clients:
                    del self.clients[client_socket]

            try:
                client_socket.close()
            except Exception:
                pass

    def _broadcast(self, sender: socket.socket, message: str):
        """Send message to all clients except the sender."""
        with self.lock:
            for client in list(self.clients.values()):
                if client != sender:
                    try:
                        client.sendall(message.encode('utf-8'))
                    except Exception:
                        pass
